CREATE TABLE products (product_id VARCHAR(100) PRIMARY KEY, product_name VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE services (service_id VARCHAR(100) PRIMARY KEY, product_id VARCHAR(100) NOT NULL REFERENCES products(product_id), service_name VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE worker_types (worker_type_id VARCHAR(100) PRIMARY KEY, service_id VARCHAR(100) NOT NULL REFERENCES services(service_id), worker_type_name VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE workers (product_id VARCHAR(100) NOT NULL REFERENCES products(product_id), service_id VARCHAR(100) NOT NULL REFERENCES services(service_id), worker_type_id VARCHAR(100) NOT NULL REFERENCES worker_types(worker_type_id), region_id INTEGER NOT NULL CHECK (region_id BETWEEN 0 AND 15), worker_id INTEGER NOT NULL, current_epoch BIGINT NOT NULL DEFAULT 0, owner_instance_id UUID, status VARCHAR(32) NOT NULL, lease_expiry TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(product_id, service_id, worker_type_id, region_id, worker_id));
CREATE TABLE worker_lease_history (id BIGSERIAL PRIMARY KEY, product_id VARCHAR(100) NOT NULL, service_id VARCHAR(100) NOT NULL, worker_type_id VARCHAR(100) NOT NULL, region_id INTEGER NOT NULL, worker_id INTEGER NOT NULL, epoch BIGINT NOT NULL, owner_instance_id UUID NOT NULL, acquired_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, released_at TIMESTAMPTZ, reason VARCHAR(64) NOT NULL, CONSTRAINT uq_worker_ownership_generation UNIQUE(product_id, service_id, worker_type_id, region_id, worker_id, epoch));
CREATE TABLE idempotency_records (operation VARCHAR(64) NOT NULL, idempotency_key UUID NOT NULL, request_fingerprint VARCHAR(128) NOT NULL, response_payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(operation, idempotency_key));
CREATE INDEX idx_workers_lease_expiry ON workers(lease_expiry);
CREATE INDEX idx_lease_history_slot ON worker_lease_history(product_id, service_id, worker_type_id, region_id, worker_id);
